-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["7c0b2931c91483f6"] = { "Khaz'goroth, il ⟦Titan=Titano⟧ che plasmò e forgiò il mondo, concesse parte del suo vasto potere al possente drago nero Neltharion. Il magnanimo Neltharion, noto in seguito come il Custode della Terra, ricevette il dominio sulla terra e sui luoghi profondi del mondo. Incarnava la forza del mondo e fu il più grande sostenitore di Alexstrasza.", "." },
  ["7c18a5979f6649c5"] = { "Illidan, divenuto dipendente dalle energie potenzianti della magia, lottava per controllare la sua fame quasi irresistibile di attingere ancora una volta alle energie del Pozzo. Tuttavia, grazie al paziente sostegno di Tyrande, riuscì a trattenersi e ad aiutare il fratello a trovare il solitario semidio Cenarius.", "." },
  ["7c586c0fe45720ea"] = { "Zampe di Cristallo -\n\nI ragni Glassweb della ⟦Searing Gorge=Gorgia Rovente⟧ sono fatti di un incredibile materiale simile al cristallo. Le loro zampe, se non si danneggiano quando vengono uccisi, sono un conduttore eccezionale per alcuni esperimenti di ingegneria dei miei colleghi.\n\nMe ne servono un certo numero per i test. Visto che ogni ragno ha ben otto zampe, per un guerriero valoroso o un mago esperto non dovrebbe essere un problema.", "." },
  ["7c5f07d24bd6947c"] = { "--Giorno 16\nUleg e Thargil sono tornati dalla loro missione al porto di Theramore. Hanno visto una nuova nave in porto: la Bleeding Sparrow. La nave è arrivata da ⟦Menethil Harbor=Porto di Menethil⟧, in Azeroth.\n\nDomani Uleg e Thargil torneranno al porto e saliranno di nascosto a bordo della nave. Sperano di trovare documenti politici, che rivelino i rapporti tra Theramore e l'⟦Alliance=Alleanza⟧.", "." },
  ["7cc905de47945c33"] = { "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align=\"center\">LE VERDI COLLINE DI ROVOTORTO</H1>\n<BR/>\n<H3 align=\"center\">di Hemet Nesingwary</H3>\n</BODY>\n</HTML>", "." },
  ["7cfa5ad3ef64044a"] = { "Saluti, Maestro,\n\nperdonami per il modo in cui ti invio questo messaggio. I miei maghi dell'ombra ad Alterac sono intenti ai loro compiti, il che mi costringe a servirmi di un messaggero straniero, reclutato tra i nostri nuovi \"alleati\", per portarti questo rapporto. Ma ho cifrato questa lettera con uno dei nostri cifrari più esoterici. Le sue parole sono al sicuro da questi zoticoni.", "." },
  ["7cfcedd83295c13e"] = { "Stranamente, poco dopo la loro miserabile vittoria Morganth si è rivoltato contro i suoi compari orchi. Lo stregone ha costruito una torre arcana a nord-est e ha usato i suoi poteri per radunare un piccolo esercito di gnoll Mantombroso al servizio dei suoi malvagi voleri. Orchi e umani sono caduti vittime dei bruti feroci che servono lo stregone. Quanto al tradimento consumatosi tra Morganth e Gath'Ilzogg, il signore della guerra dei ⟦Blackrock=Roccianera⟧, per ora si possono fare solo congetture.", "." },
})
